def earliest_arrival(n, runs, src, dst, t0):
    INF = float("inf")
    best = [INF] * n
    best[src] = t0
    for a, b, depart, arrive in sorted(runs, key=lambda run: run[2]):
        if best[a] <= depart and arrive < best[b]:
            best[b] = arrive
    return -1 if best[dst] == INF else best[dst]

